INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2c8000in8e1d9dqreq9', 'cmvtuo29v0000n8e1z5jjc9b0', 'cmvtuo2ah0006n8e142axj37m', 'MCQ', 'Which of the following is NOT an operating system function?', NULL, '[{"id":"A","text":"Memory management"},{"id":"B","text":"Process scheduling"},{"id":"C","text":"Compiler design"},{"id":"D","text":"File management"}]', NULL, 'C', 'Compiler design is not a core OS function; memory management, process scheduling, and file management are.', NULL, 2024, 'pyq', 'easy', 5, 1, 1, '2026-10-29T18:01:32.889Z', '2026-10-29T18:01:32.990Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2cd000kn8e15rctde0b', 'cmvtuo29v0000n8e1z5jjc9b0', 'cmvtuo2ah0006n8e142axj37m', 'MCQ', 'In Round Robin scheduling, the time allocated to each process is called:', NULL, '[{"id":"A","text":"Burst time"},{"id":"B","text":"Time quantum"},{"id":"C","text":"Waiting time"},{"id":"D","text":"Turnaround time"}]', NULL, 'B', 'Time quantum is the fixed time slice assigned to each process in Round Robin.', NULL, NULL, 'sample', 'easy', 5, 1, 1, '2026-10-29T18:01:32.893Z', '2026-10-29T18:01:32.893Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2ch000mn8e1oai0vdc5', 'cmvtuo29v0000n8e1z5jjc9b0', 'cmvtuo2ah0008n8e1j68jojcr', 'MCQ', 'Which normal form eliminates transitive dependencies?', NULL, '[{"id":"A","text":"1NF"},{"id":"B","text":"2NF"},{"id":"C","text":"3NF"},{"id":"D","text":"BCNF"}]', NULL, 'C', '3NF eliminates transitive dependencies where a non-prime attribute depends on another non-prime attribute.', NULL, 2022, 'pyq', 'medium', 5, 1, 1, '2026-10-29T18:01:32.897Z', '2026-10-29T18:01:32.995Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2cl000on8e13eqpvvkv', 'cmvtuo29v0000n8e1z5jjc9b0', 'cmvtuo2ah0008n8e1j68jojcr', 'MCQ', 'ACID stands for:', NULL, '[{"id":"A","text":"Atomicity, Consistency, Isolation, Durability"},{"id":"B","text":"Atomicity, Concurrency, Isolation, Durability"},{"id":"C","text":"Availability, Consistency, Isolation, Durability"},{"id":"D","text":"Atomicity, Consistency, Integrity, Durability"}]', NULL, 'A', 'ACID = Atomicity, Consistency, Isolation, Durability — the four properties of database transactions.', NULL, NULL, 'sample', 'easy', 5, 1, 1, '2026-10-29T18:01:32.901Z', '2026-10-29T18:01:32.901Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2co000qn8e16gi144qs', 'cmvtuo29v0000n8e1z5jjc9b0', 'cmvtuo2ah0007n8e1xzh7128p', 'MCQ', 'The time complexity of binary search on a sorted array of n elements is:', NULL, '[{"id":"A","text":"O(n)"},{"id":"B","text":"O(n log n)"},{"id":"C","text":"O(log n)"},{"id":"D","text":"O(n²)"}]', NULL, 'C', 'Binary search halves the search space each step, giving O(log n) time complexity.', NULL, 2024, 'pyq', 'easy', 5, 1, 1, '2026-10-29T18:01:32.905Z', '2026-10-29T18:01:32.999Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2cs000sn8e16c0oz78p', 'cmvtuo29v0000n8e1z5jjc9b0', 'cmvtuo2ah0007n8e1xzh7128p', 'MCQ', 'Which data structure uses LIFO order?', NULL, '[{"id":"A","text":"Queue"},{"id":"B","text":"Stack"},{"id":"C","text":"Array"},{"id":"D","text":"Hash table"}]', NULL, 'B', 'Stack follows Last-In-First-Out (LIFO) order.', NULL, NULL, 'sample', 'easy', 5, 1, 1, '2026-10-29T18:01:32.908Z', '2026-10-29T18:01:32.908Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2cx000un8e1iua1t5h6', 'cmvtuo29v0000n8e1z5jjc9b0', 'cmvtuo2ah0006n8e142axj37m', 'MCQ', 'A deadlock occurs when:', NULL, '[{"id":"A","text":"A process waits for a resource held by another waiting process"},{"id":"B","text":"Two processes run simultaneously"},{"id":"C","text":"Memory is full"},{"id":"D","text":"CPU is idle"}]', NULL, 'A', 'Deadlock is a circular wait condition where processes wait for resources held by each other.', NULL, 2022, 'pyq', 'medium', 5, 1, 1, '2026-10-29T18:01:32.913Z', '2026-10-29T18:01:33.002Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2d1000wn8e15nj29vmz', 'cmvtuo29v0000n8e1z5jjc9b0', 'cmvtuo2ah0008n8e1j68jojcr', 'MCQ', 'SQL command to remove a table and its data:', NULL, '[{"id":"A","text":"DELETE"},{"id":"B","text":"DROP"},{"id":"C","text":"TRUNCATE"},{"id":"D","text":"REMOVE"}]', NULL, 'B', 'DROP TABLE removes the table definition and all data. DELETE removes rows; TRUNCATE removes rows but keeps table.', NULL, NULL, 'sample', 'easy', 5, 1, 1, '2026-10-29T18:01:32.917Z', '2026-10-29T18:01:32.917Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2d4000yn8e1fxd8npu3', 'cmvtuo29v0000n8e1z5jjc9b0', 'cmvtuo2ah0007n8e1xzh7128p', 'MCQ', 'In a min-heap, the smallest element is always at:', NULL, '[{"id":"A","text":"A leaf node"},{"id":"B","text":"The root"},{"id":"C","text":"Any internal node"},{"id":"D","text":"The last level"}]', NULL, 'B', 'In a min-heap, the root is always the minimum element.', NULL, 2024, 'pyq', 'easy', 5, 1, 1, '2026-10-29T18:01:32.921Z', '2026-10-29T18:01:33.005Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2d80010n8e1uvmmkfv1', 'cmvtuo29v0000n8e1z5jjc9b0', 'cmvtuo2ah0006n8e142axj37m', 'MCQ', 'Virtual memory allows:', NULL, '[{"id":"A","text":"Running programs larger than physical RAM"},{"id":"B","text":"Disabling the CPU"},{"id":"C","text":"Removing the need for a hard disk"},{"id":"D","text":"Running only one program"}]', NULL, 'A', 'Virtual memory uses disk space to extend RAM, allowing programs larger than physical memory to run.', NULL, NULL, 'sample', 'medium', 5, 1, 1, '2026-10-29T18:01:32.924Z', '2026-10-29T18:01:32.924Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2dc0012n8e1fe6oy9gd', 'cmvtuo2a80001n8e1l0yjf20y', 'cmvtuo2be000bn8e1h5wx3fub', 'MCQ', 'A body of mass 2 kg moves with velocity 5 m/s. Its kinetic energy is:', NULL, '[{"id":"A","text":"10 J"},{"id":"B","text":"25 J"},{"id":"C","text":"50 J"},{"id":"D","text":"5 J"}]', NULL, 'B', 'KE = ½mv² = ½ × 2 × 5² = 25 J.', NULL, 2022, 'pyq', 'easy', 5, 1, 1, '2026-10-29T18:01:32.928Z', '2026-10-29T18:01:33.009Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2dg0014n8e1smk8ex3h', 'cmvtuo2a80001n8e1l0yjf20y', 'cmvtuo2be000bn8e1h5wx3fub', 'MCQ', 'Newton''s first law is also called the law of:', NULL, '[{"id":"A","text":"Inertia"},{"id":"B","text":"Acceleration"},{"id":"C","text":"Action-reaction"},{"id":"D","text":"Gravitation"}]', NULL, 'A', 'Newton''s first law is the law of inertia.', NULL, NULL, 'sample', 'easy', 5, 1, 1, '2026-10-29T18:01:32.932Z', '2026-10-29T18:01:32.932Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2dj0016n8e1u4r6pds0', 'cmvtuo2a80001n8e1l0yjf20y', 'cmvtuo2be000cn8e1n4zayy1i', 'MCQ', 'Ohm''s law states:', NULL, '[{"id":"A","text":"V = IR"},{"id":"B","text":"V = I/R"},{"id":"C","text":"I = VR"},{"id":"D","text":"R = VI"}]', NULL, 'A', 'Ohm''s law: Voltage = Current × Resistance (V = IR).', NULL, 2024, 'pyq', 'easy', 5, 1, 1, '2026-10-29T18:01:32.935Z', '2026-10-29T18:01:33.012Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2dm0018n8e1fftqtdqi', 'cmvtuo2a80001n8e1l0yjf20y', 'cmvtuo2be000cn8e1n4zayy1i', 'MCQ', 'The unit of electric charge is:', NULL, '[{"id":"A","text":"Volt"},{"id":"B","text":"Ampere"},{"id":"C","text":"Coulomb"},{"id":"D","text":"Watt"}]', NULL, 'C', 'Coulomb is the SI unit of electric charge.', NULL, NULL, 'sample', 'easy', 5, 1, 1, '2026-10-29T18:01:32.939Z', '2026-10-29T18:01:32.939Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2dq001an8e1aq25urlp', 'cmvtuo2a80001n8e1l0yjf20y', 'cmvtuo2be000bn8e1h5wx3fub', 'MCQ', 'Work done by a force of 10 N moving an object 3 m in force direction:', NULL, '[{"id":"A","text":"3 J"},{"id":"B","text":"30 J"},{"id":"C","text":"13 J"},{"id":"D","text":"3.33 J"}]', NULL, 'B', 'Work = Force × Distance = 10 × 3 = 30 J.', NULL, 2022, 'pyq', 'easy', 5, 1, 1, '2026-10-29T18:01:32.943Z', '2026-10-29T18:01:33.016Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2du001cn8e1ur1r7vu4', 'cmvtuo2a80001n8e1l0yjf20y', 'cmvtuo2be000bn8e1h5wx3fub', 'MCQ', 'Momentum = mass × ?', NULL, '[{"id":"A","text":"Velocity"},{"id":"B","text":"Acceleration"},{"id":"C","text":"Force"},{"id":"D","text":"Time"}]', NULL, 'A', 'Momentum p = mv, where v is velocity.', NULL, NULL, 'sample', 'easy', 5, 1, 1, '2026-10-29T18:01:32.946Z', '2026-10-29T18:01:32.946Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2dy001en8e1f1175e0c', 'cmvtuo2a80001n8e1l0yjf20y', 'cmvtuo2be000cn8e1n4zayy1i', 'MCQ', 'In a series circuit, current:', NULL, '[{"id":"A","text":"Is same through all components"},{"id":"B","text":"Divides among components"},{"id":"C","text":"Is zero"},{"id":"D","text":"Doubles"}]', NULL, 'A', 'In series, the same current flows through every component.', NULL, 2024, 'pyq', 'easy', 5, 1, 1, '2026-10-29T18:01:32.950Z', '2026-10-29T18:01:33.020Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2e1001gn8e1orxj66o4', 'cmvtuo2a80001n8e1l0yjf20y', 'cmvtuo2be000cn8e1n4zayy1i', 'MCQ', 'Power = Voltage × ?', NULL, '[{"id":"A","text":"Current"},{"id":"B","text":"Resistance"},{"id":"C","text":"Charge"},{"id":"D","text":"Energy"}]', NULL, 'A', 'Electrical power P = V × I.', NULL, NULL, 'sample', 'easy', 5, 1, 1, '2026-10-29T18:01:32.954Z', '2026-10-29T18:01:32.954Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2e5001in8e167u54mew', 'cmvtuo2ac0002n8e1essezmcm', 'cmvtuo2bt000fn8e1culdmjoa', 'MCQ', 'Find the missing number: 2, 6, 12, 20, ?, 42', NULL, '[{"id":"A","text":"28"},{"id":"B","text":"30"},{"id":"C","text":"32"},{"id":"D","text":"34"}]', NULL, 'B', 'Pattern: n×(n+1): 1×2=2, 2×3=6, 3×4=12, 4×5=20, 5×6=30, 6×7=42.', NULL, 2022, 'pyq', 'easy', 5, 1, 1, '2026-10-29T18:01:32.957Z', '2026-10-29T18:01:33.024Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2e8001kn8e1xgceroof', 'cmvtuo2ac0002n8e1essezmcm', 'cmvtuo2bt000fn8e1culdmjoa', 'MCQ', 'If A is brother of B, and B is sister of C, then A is C''s:', NULL, '[{"id":"A","text":"Brother"},{"id":"B","text":"Sister"},{"id":"C","text":"Father"},{"id":"D","text":"Uncle"}]', NULL, 'A', 'A (male) is B''s brother; B is C''s sister; so A is C''s brother.', NULL, NULL, 'sample', 'easy', 5, 1, 1, '2026-10-29T18:01:32.961Z', '2026-10-29T18:01:32.961Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2ec001mn8e1t9ytxm7u', 'cmvtuo2ac0002n8e1essezmcm', 'cmvtuo2bt000gn8e1vxzbnmvu', 'MCQ', '15% of 200 = ?', NULL, '[{"id":"A","text":"20"},{"id":"B","text":"30"},{"id":"C","text":"25"},{"id":"D","text":"35"}]', NULL, 'B', '15% of 200 = 0.15 × 200 = 30.', NULL, NULL, 'sample', 'easy', 5, 1, 1, '2026-10-29T18:01:32.965Z', '2026-10-29T18:01:32.965Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2eg001on8e1gxn614gh', 'cmvtuo2ac0002n8e1essezmcm', 'cmvtuo2bt000gn8e1vxzbnmvu', 'MCQ', 'A train travels 240 km in 4 hours. Its speed is:', NULL, '[{"id":"A","text":"50 km/h"},{"id":"B","text":"60 km/h"},{"id":"C","text":"70 km/h"},{"id":"D","text":"80 km/h"}]', NULL, 'B', 'Speed = Distance / Time = 240 / 4 = 60 km/h.', NULL, NULL, 'sample', 'easy', 5, 1, 1, '2026-10-29T18:01:32.969Z', '2026-10-29T18:01:32.969Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2el001qn8e1qafi9uqj', 'cmvtuo2ac0002n8e1essezmcm', 'cmvtuo2bt000fn8e1culdmjoa', 'MCQ', 'Complete the series: AZ, BY, CX, ?', NULL, '[{"id":"A","text":"DW"},{"id":"B","text":"DX"},{"id":"C","text":"EW"},{"id":"D","text":"DV"}]', NULL, 'A', 'First letter advances A→B→C→D; second letter recedes Z→Y→X→W.', NULL, NULL, 'sample', 'easy', 5, 1, 1, '2026-10-29T18:01:32.974Z', '2026-10-29T18:01:32.974Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2eq001sn8e119fypax9', 'cmvtuo2ac0002n8e1essezmcm', 'cmvtuo2bt000gn8e1vxzbnmvu', 'MCQ', 'Simple interest on ₹1000 at 10% per annum for 2 years:', NULL, '[{"id":"A","text":"₹100"},{"id":"B","text":"₹200"},{"id":"C","text":"₹150"},{"id":"D","text":"₹250"}]', NULL, 'B', 'SI = P×R×T/100 = 1000×10×2/100 = ₹200.', NULL, NULL, 'sample', 'easy', 5, 1, 1, '2026-10-29T18:01:32.978Z', '2026-10-29T18:01:32.978Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2et001un8e1qct7hf27', 'cmvtuo2ac0002n8e1essezmcm', 'cmvtuo2bt000fn8e1culdmjoa', 'MCQ', 'Odd one out: 3, 5, 7, 9, 11', NULL, '[{"id":"A","text":"3"},{"id":"B","text":"7"},{"id":"C","text":"9"},{"id":"D","text":"11"}]', NULL, 'C', '9 is not a prime number; all others are prime.', NULL, NULL, 'sample', 'easy', 5, 1, 1, '2026-10-29T18:01:32.982Z', '2026-10-29T18:01:32.982Z');
INSERT INTO "Question" ("id", "subjectId", "chapterId", "type", "stemEn", "stemHi", "optionsEn", "optionsHi", "correctAnswer", "explanationEn", "explanationHi", "year", "source", "difficulty", "marks", "negativeMarks", "isActive", "createdAt", "updatedAt") VALUES ('cmvtuo2ex001wn8e1a3b3xb47', 'cmvtuo2ac0002n8e1essezmcm', 'cmvtuo2bt000gn8e1vxzbnmvu', 'MCQ', 'If 5 workers build a wall in 12 days, how many days for 3 workers?', NULL, '[{"id":"A","text":"15"},{"id":"B","text":"20"},{"id":"C","text":"25"},{"id":"D","text":"30"}]', NULL, 'B', 'Total work = 5×12 = 60 worker-days. 3 workers take 60/3 = 20 days.', NULL, NULL, 'sample', 'medium', 5, 1, 1, '2026-10-29T18:01:32.985Z', '2026-10-29T18:01:32.985Z');
